#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int lengthLongestPath(char* input) {
    int n = (int)strlen(input);
    int* path_len = (int*)calloc((size_t)n + 2, sizeof(int));
    if (path_len == NULL) return 0;

    int best = 0;
    int start = 0;

    while (start <= n) {
        int end = start;
        while (end < n && input[end] != '\n') end++;

        int depth = 0;
        while (start + depth < end && input[start + depth] == '\t') depth++;

        int name_start = start + depth;
        int name_len = end - name_start;
        int is_file = 0;

        for (int i = name_start; i < end; ++i) {
            if (input[i] == '.') {
                is_file = 1;
                break;
            }
        }

        if (is_file) {
            int candidate = path_len[depth] + name_len;
            if (candidate > best) best = candidate;
        } else {
            path_len[depth + 1] = path_len[depth] + name_len + 1;
        }

        if (end == n) break;
        start = end + 1;
    }

    free(path_len);
    return best;
}

static char* read_json_string(const char* line) {
    const char* p = strchr(line, '"');
    if (p == NULL) return NULL;
    ++p;

    size_t cap = strlen(line) + 1;
    char* out = (char*)malloc(cap);
    if (out == NULL) return NULL;

    size_t j = 0;
    while (*p != '\0') {
        char c = *p++;
        if (c == '"') break;

        if (c == '\\' && *p != '\0') {
            char e = *p++;
            if (e == 'n') out[j++] = '\n';
            else if (e == 't') out[j++] = '\t';
            else if (e == 'r') out[j++] = '\r';
            else if (e == '\\') out[j++] = '\\';
            else if (e == '"') out[j++] = '"';
            else out[j++] = e;
        } else {
            out[j++] = c;
        }
    }

    out[j] = '\0';
    return out;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    char* input = read_json_string(line);
    if (input == NULL) return 0;

    printf("%d\n", lengthLongestPath(input));
    free(input);
    return 0;
