using namespace std;

class Solution {
public:
    int lengthLongestPath(string input) {
        vector<int> pathLen(input.size() + 2, 0);
        int best = 0;

        size_t start = 0;
        while (start <= input.size()) {
            size_t end = input.find('\n', start);
            if (end == string::npos) end = input.size();

            int depth = 0;
            while (start + depth < end && input[start + depth] == '\t') {
                depth++;
            }

            size_t nameStart = start + depth;
            int nameLen = static_cast<int>(end - nameStart);
            bool isFile = input.find('.', nameStart) != string::npos &&
                          input.find('.', nameStart) < end;

            if (isFile) {
                best = max(best, pathLen[depth] + nameLen);
            } else {
                pathLen[depth + 1] = pathLen[depth] + nameLen + 1;
            }

            if (end == input.size()) break;
            start = end + 1;
        }

        return best;
    }
};

static string readJsonString(const string& line) {
    size_t i = line.find('"');
    if (i == string::npos) return "";
    ++i;

    string out;
    while (i < line.size()) {
        char c = line[i++];
        if (c == '"') break;

        if (c == '\\' && i < line.size()) {
            char e = line[i++];
            if (e == 'n') out.push_back('\n');
            else if (e == 't') out.push_back('\t');
            else if (e == 'r') out.push_back('\r');
            else if (e == '\\') out.push_back('\\');
            else if (e == '"') out.push_back('"');
            else out.push_back(e);
        } else {
            out.push_back(c);
        }
    }
    return out;
}

