import java.io.*;

class Solution {
    public int lengthLongestPath(String input) {
        int[] pathLen = new int[input.length() + 2];
        int best = 0;

        String[] lines = input.split("\\n", -1);
        for (String line : lines) {
            int depth = 0;
            while (depth < line.length() && line.charAt(depth) == '\t') {
                depth++;
            }
            String name = line.substring(depth);

            if (name.indexOf('.') >= 0) {
                best = Math.max(best, pathLen[depth] + name.length());
            } else {
                pathLen[depth + 1] = pathLen[depth] + name.length() + 1;
            }
        }

        return best;
    }
}

public class Main {
    static String readJsonString(String line) {
        int i = 0;
        while (i < line.length() && line.charAt(i) != '"') i++;
        if (i == line.length()) return "";

        i++;
        StringBuilder out = new StringBuilder();
        while (i < line.length()) {
            char c = line.charAt(i++);
            if (c == '"') break;
            if (c == '\\') {
                if (i >= line.length()) break;
                char e = line.charAt(i++);
                if (e == 'n') out.append('\n');
                else if (e == 't') out.append('\t');
                else if (e == 'r') out.append('\r');
                else if (e == '\\') out.append('\\');
                else if (e == '"') out.append('"');
                else out.append(e);
            } else {
                out.append(c);
            }
        }
        return out.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        String input = readJsonString(line.trim());
        System.out.println(new Solution().lengthLongestPath(input));
    }
}

