'use strict';

function lengthLongestPath(input) {
    const pathLen = new Array(input.length + 2).fill(0);
    let best = 0;

    for (const line of input.split('\n')) {
        let depth = 0;
        while (depth < line.length && line[depth] === '\t') depth++;
        const name = line.slice(depth);

        if (name.includes('.')) {
            best = Math.max(best, pathLen[depth] + name.length);
        } else {
            pathLen[depth + 1] = pathLen[depth] + name.length + 1;
        }
    }

    return best;
}

